import{_ as a,a as t,c as i,j as n}from"./chunks/framework.DVzkjf-b.js";const g=JSON.parse('{"title":"From Claims to Navigable Knowledge","description":"A design thesis for provenance-backed claims, two distinct graphs, contextual search, generated dossiers, and a decision-oriented briefing interface.","frontmatter":{"title":"From Claims to Navigable Knowledge","description":"A design thesis for provenance-backed claims, two distinct graphs, contextual search, generated dossiers, and a decision-oriented briefing interface."},"headers":[],"relativePath":"research/systems/vision-and-interface.md","filePath":"research/systems/vision-and-interface.md"}'),r={name:"research/systems/vision-and-interface.md"};function s(o,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="from-claims-to-navigable-knowledge" tabindex="-1">From Claims to Navigable Knowledge <a class="header-anchor" href="#from-claims-to-navigable-knowledge" aria-label="Permalink to &quot;From Claims to Navigable Knowledge&quot;">​</a></h1><p><em>Architecture and interface thesis · November 2026 · Proposed, not a deployed system</em></p><p>I want people to move naturally between an intelligence briefing, a readable topic page, a network of related information, and the original evidence. The user should not have to learn the structure of a graph database or the internals of an LLM.</p><p>The long-term goal is <strong>personalized knowledge artifacts</strong>: an evidence-linked explanation, a visual investigation, a technical report, an audio overview, or a decision brief generated from the same governed foundation.</p><h2 id="the-central-design-decision-claims-come-first" tabindex="-1">The central design decision: claims come first <a class="header-anchor" href="#the-central-design-decision-claims-come-first" aria-label="Permalink to &quot;The central design decision: claims come first&quot;">​</a></h2><p>The canonical unit is an <strong>attributed, evidence-backed claim</strong>, not an unquestioned graph edge.</p><p>An archive can establish that an agency published a report; it does not automatically establish the truth of every statement in the report. Multiple websites repeating a source do not create independent corroboration. A generated summary does not become a second source confirming the first.</p><p>Each consequential assessment should answer:</p><ol><li><strong>What do we know?</strong> The exact reported observations and the available sources.</li><li><strong>Why do we believe it?</strong> Citations, interpretation, source dependence, alternatives, and qualifications.</li><li><strong>What would change our assessment?</strong> Missing or contrary evidence, measurement limitations, or unresolved identities.</li></ol><p>This is accountable analysis, <strong>not</strong> a claim that software can determine the ultimate truth of disputed history.</p><h2 id="two-different-graphs" tabindex="-1">Two different graphs <a class="header-anchor" href="#two-different-graphs" aria-label="Permalink to &quot;Two different graphs&quot;">​</a></h2><p>A page-link graph and an evidence graph should be connected, but never conflated.</p><table tabindex="0"><thead><tr><th>Navigation graph</th><th>Evidence and assertion graph</th></tr></thead><tbody><tr><td><strong>Nodes:</strong> generated or published topic pages</td><td><strong>Nodes:</strong> sources, passages, people, events, claims, assessments</td></tr><tr><td><strong>Edges:</strong> hyperlinks between pages</td><td><strong>Edges:</strong> explicitly typed, evidence-cited relationships</td></tr><tr><td>Optimized for exploration, orientation and reading</td><td>Optimized for provenance, qualification and investigation</td></tr><tr><td>A link says “this page leads to that page”</td><td>A claim says “this source reports this proposition”</td></tr></tbody></table><p>The navigation graph lets the user move through knowledge like a networked book. The evidence graph lets the user inspect why pages contain a statement. One hyperlink is not proof of a relationship.</p><h2 id="wikipedia-and-wikidata-are-external-sources-not-ui-templates" tabindex="-1">Wikipedia and Wikidata are external sources, not UI templates <a class="header-anchor" href="#wikipedia-and-wikidata-are-external-sources-not-ui-templates" aria-label="Permalink to &quot;Wikipedia and Wikidata are external sources, not UI templates&quot;">​</a></h2><p>Wikipedia is useful for topic discovery: linked pages, anchor text, article sections, references and surrounding context can reveal candidate entities and relation types. <a href="https://www.wikidata.org/wiki/Wikidata:Data_model" target="_blank" rel="noreferrer">Wikidata</a> supplies reusable identifiers, aliases, typed properties, qualifiers and references. <a href="https://www.wikidata.org/wiki/Help:Data_access" target="_blank" rel="noreferrer">https://www.wikidata.org/wiki/Help:Data_access</a></p><p>The system should save a local entity identity, candidate Wikidata identifiers, source revisions and the evidence behind disambiguation. Wikipedia&#39;s linked context may <em>suggest</em> a relationship; it cannot silently certify one.</p><p>The UI remains independent of Wikipedia. It identifies Wikipedia as <strong>one named external source</strong> when used and prefers original material where the question demands it. A page cannot cite its own generated summary as fresh corroboration.</p><h2 id="the-intended-interface" tabindex="-1">The intended interface <a class="header-anchor" href="#the-intended-interface" aria-label="Permalink to &quot;The intended interface&quot;">​</a></h2><p>The user arrives at an <strong>intelligence briefing</strong>, not a database administration dashboard.</p><p><strong>Briefing</strong> — the most relevant changes, conclusions, unresolved questions, risks and recommended next decisions. Each claim can open a transparent evidence trail.</p><p><strong>Dynamic dossier</strong> — a readable, versioned page about an entity or event, with an overview, chronology, cited claims, competing interpretations, and linked subtopics. It is generated from qualified information, not treated as a primary source.</p><p><strong>Graph explorer</strong> — a focused neighborhood of connected pages, entities or claims; selecting a node opens an appropriate dossier or evidence view. Showing a billion nodes at once is not useful.</p><p><strong>Semantic and exact search</strong> — retrieves concepts, source spans, names and identifiers; search can progressively expand into graph relationships and provenance.</p><p><strong>Evidence and Five Whys explorer</strong> — exposes what was said, the original span or timecode, intermediate transformations, conflicts, and the reasons an assessment was made. A Five Whys trace is an <em>investigation prompt</em>, not an automatically correct causal explanation.</p><p>A contextual assistant should follow the selected claim, entity, and page rather than becoming a disconnected chatbot. A reader can ask “Why is this relationship here?”, “Who is the original source?”, “What changed?”, and “Show the other interpretation.”</p><h2 id="how-ordo-informs-this-interface" tabindex="-1">How Ordo informs this interface <a class="header-anchor" href="#how-ordo-informs-this-interface" aria-label="Permalink to &quot;How Ordo informs this interface&quot;">​</a></h2><p>The earlier <a href="https://github.com/kaw393939/ordo/blob/main/development-docs/PRODUCT-UX.md" target="_blank" rel="noreferrer">Ordo Product &amp; UX Model</a> already specifies daily briefings, persistent artifacts, contextual conversation, progressive disclosure, and explicit approval actions.</p><p>Its <a href="https://github.com/kaw393939/ordo/blob/main/agentic-appliance/architecture/briefing-ui-runtime.md" target="_blank" rel="noreferrer">Briefing UI Runtime</a> states the key design principle: <em>the page is the artifact; the AI is the operator; chat is the control surface</em>. The <a href="https://github.com/kaw393939/ordo/blob/main/agentic-appliance/patterns/artifact-spec-renderer.md" target="_blank" rel="noreferrer">Artifact Spec Renderer</a> proposes a typed artifact rendered into multiple formats.</p><p>These are documented designs, <strong>not evidence of a shipped native Swift graph application</strong>. The proposed runtime should keep evidence stores, rendering schemas, and UI clients separate; a native Swift UI and a web client could render the same versioned knowledge artifacts.</p><h2 id="briefing-as-a-quality-standard-not-military-styling" tabindex="-1">Briefing as a quality standard, not military styling <a class="header-anchor" href="#briefing-as-a-quality-standard-not-military-styling" aria-label="Permalink to &quot;Briefing as a quality standard, not military styling&quot;">​</a></h2><p>The intelligence briefing metaphor is useful because the user needs concise, consequential analysis with drill-down. <a href="https://www.intelligence.gov/mission/our-values/objectivity" target="_blank" rel="noreferrer">ICD 203</a> describes relevant analytic tradecraft: qualify sources, explain uncertainty, distinguish information from judgments, consider alternatives, identify changes and provide useful visual aids.</p><p>The system should help an operator understand decisions without hiding evidence or overclaiming authority. Source credibility, claim support, transcription confidence, and reviewer authorization must remain distinguishable.</p><h2 id="what-needs-empirical-evaluation" tabindex="-1">What needs empirical evaluation <a class="header-anchor" href="#what-needs-empirical-evaluation" aria-label="Permalink to &quot;What needs empirical evaluation&quot;">​</a></h2><p>The interface is a hypothesis. Research should compare a briefing + optional evidence path with a raw-document list and an ordinary chat interface. Outcomes include finding and correcting a false source link, identifying a copied claim, reconstructing why an assessment changed, decision accuracy, time, and cognitive load.</p><p>The system should also test whether its <strong>navigation graph</strong> genuinely improves exploration or merely adds visual complexity. The correct design is the one that helps users accomplish tasks.</p><h2 id="related-2026-research" tabindex="-1">Related 2026 research <a class="header-anchor" href="#related-2026-research" aria-label="Permalink to &quot;Related 2026 research&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2606.15246" target="_blank" rel="noreferrer">Vitali and Pasqual, <em>Provenance-Enhanced Statements in Knowledge Graphs</em> (2026 preprint)</a> addresses attributed claims and competing epistemic stances.</li><li><a href="https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7525242" target="_blank" rel="noreferrer">Kakatkar and Khatib, <em>Epistemic Knowledge Graphs</em> (2026 working paper)</a> formalizes epistemic status, provenance and claim-level explanations.</li><li><a href="https://doi.org/10.1145/3795134" target="_blank" rel="noreferrer"><em>Entity Linking with Wikidata: A Systematic Literature Review</em> (2026)</a> documents prior work on entity disambiguation and areas such as temporal and qualified relations.</li></ul><p>These publications are <strong>prior art</strong>, not evidence of an original invention here. The research contribution would have to be tested against this scholarship.</p><p><a href="./">Research hub</a> · <a href="./uap-research-testbed">Why UAP is the testbed</a> · <a href="./dissertation-proposal">Advisor proposal</a></p>',40)])])}const m=a(r,[["render",s]]);export{g as __pageData,m as default};
